// Java Kafka producer snippet showing recommended durability/throughput knobs
Properties props = new Properties();
props.put("bootstrap.servers", "kafka1:9092,kafka2:9092");
props.put("acks", "all"); // durability
props.put("compression.type", "snappy"); // reduce network/disk
props.put("batch.size", 65536); // larger batches
props.put("linger.ms", 10); // wait up to 10ms to batch
props.put("retries", 3);
props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

KafkaProducer<String, String> producer = new KafkaProducer<>(props);
producer.send(new ProducerRecord<>("user-actions", userId, payload));
producer.flush();
producer.close();

